        let mut r = G1Region::new(1024);
        r.set_region_type(RegionType::Old);
        r.set_cursor(500);
        r.live_bytes = 200;
        r.gc_efficiency = r.live_bytes as f64 / 1024.0;
        assert!(r.gc_efficiency < 0.2);
